--root package.json--
{
  "name": "antarya",
  "version": "1.0.0",
  "description": "Antarya – Dukan Ka Dimaag (Shop's Brain)",
  "scripts": {
    "dev": "concurrently \"npm --prefix server run dev\" \"npm --prefix client run dev\"",
    "server": "npm --prefix server run dev",
    "client": "npm --prefix client run dev",
    "install:all": "npm install && npm --prefix server install && npm --prefix client install"
  },
  "devDependencies": {
    "concurrently": "^8.2.2"
  }
}
--db.js--
const mongoose = require('mongoose');

const connectDB = async () => {
  console.log('--- Startup Diagnostics ---');
  console.log('MONGO_URI exists:', !!process.env.MONGO_URI);
  console.log('GEMINI_API_KEY exists:', !!process.env.GEMINI_API_KEY);
  console.log('JWT_SECRET exists:', !!process.env.JWT_SECRET);
  console.log('PORT:', process.env.PORT || 5001);
  console.log('---------------------------');

  if (process.env.MONGO_URI) {
    try {
      const conn = await mongoose.connect(process.env.MONGO_URI, { family: 4, serverSelectionTimeoutMS: 5000 });
      console.log(`✅ MongoDB Connected: ${conn.connection.host}`);
      return;
    } catch (error) {
      console.error(`❌ MongoDB Connection Error: ${error.message}`);
    }
  }

  // Fallback to in-memory DB if MONGO_URI is missing or fails to connect
  console.log(`\n⚠️  LAUNCHING LOCAL IN-MEMORY MONGODB FOR DUKUAN...`);
  try {
    const { MongoMemoryServer } = require('mongodb-memory-server');
    const mongoServer = await MongoMemoryServer.create({
      instance: { storageEngine: 'wiredTiger' },
      binary: { downloadDir: require('path').join(__dirname, '.cache', 'mongodb-binaries') }
    });
    const memUri = mongoServer.getUri();
    const conn = await mongoose.connect(memUri);
    console.log(`✅ In-Memory MongoDB Connected successfully at ${memUri}!`);
  } catch (fallbackError) {
    console.error(`❌ In-Memory MongoDB fallback failed: ${fallbackError.message}`);
    process.exit(1);
  }
};

const shopSchema = new mongoose.Schema({
  id: { type: String, required: true, unique: true }, // keeping id for backward compatibility
  phone: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  name: { type: String, required: true },
  ownerName: { type: String, required: true },
  city: { type: String },
  setupComplete: { type: Boolean, default: false }
}, { timestamps: true });

const productSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  name: { type: String, required: true },
  nameHindi: { type: String },
  emoji: { type: String, default: '📦' },
  sellingPrice: { type: Number, required: true },
  costPrice: { type: Number, required: true },
  unit: { type: String, default: 'pc' },
  category: { type: String, default: 'General' },
  quantity: { type: Number, default: 0 },
  minStock: { type: Number, default: 5 }
}, { timestamps: true });

const customerSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  name: { type: String, required: true },
  phone: { type: String },
  totalSpent: { type: Number, default: 0 },
  totalCredit: { type: Number, default: 0 }, // positive means they owe money (udhaar)
  lastVisit: { type: Date }
}, { timestamps: true });

const saleSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  amount: { type: Number, required: true },
  method: { type: String, enum: ['cash', 'upi', 'udhaar'], required: true },
  items: [{
    productId: { type: String },
    name: { type: String },
    qty: { type: Number },
    price: { type: Number }
  }],
  customerId: { type: String }, // optional, for udhaar
  timestamp: { type: Date, default: Date.now }
});

const expenseSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  amount: { type: Number, required: true },
  category: { type: String, required: true },
  note: { type: String },
  month: { type: String }, // e.g. "April 2026"
  date: { type: String }, // e.g. "2026-04-18"
  timestamp: { type: Date, default: Date.now }
});

const complaintSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  customer: { type: String, required: true },
  issue: { type: String, required: true },
  status: { type: String, enum: ['open', 'resolved'], default: 'open' },
  suggestedReply: { type: String },
  replySent: { type: String },
  priority: { type: String, enum: ['high', 'medium', 'low'], default: 'medium' },
  timestamp: { type: Date, default: Date.now }
});

const predictionLogSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  productId: { type: String, required: true },
  productName: { type: String, required: true },
  predictedDemand: { type: Number, required: true },
  confidence: { type: Number },
  modelVersion: { type: String, required: true },
  modelType: { type: String, enum: ['foundation', 'hybrid', 'local'], default: 'foundation' },
  timestamp: { type: Date, default: Date.now }
});

const actualLogSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  productId: { type: String, required: true },
  productName: { type: String, required: true },
  actualSales: { type: Number, required: true },
  predictionLogId: { type: String }, // Links to the prediction
  absoluteError: { type: Number },
  percentageError: { type: Number },
  timestamp: { type: Date, default: Date.now }
});

const modelRegistrySchema = new mongoose.Schema({
  shopId: { type: String, required: true }, // "global" for foundation model
  version: { type: String, required: true },
  type: { type: String, enum: ['foundation', 'hybrid', 'local'], required: true },
  trainedAt: { type: Date, default: Date.now },
  status: { type: String, enum: ['active', 'staged', 'retired'], default: 'active' },
  trainingRows: { type: Number }
});

// Add performance indexes for fast shopId and timestamp queries
productSchema.index({ shopId: 1, id: 1 });
customerSchema.index({ shopId: 1, id: 1 });
saleSchema.index({ shopId: 1, timestamp: -1 });
expenseSchema.index({ shopId: 1, timestamp: -1 });
complaintSchema.index({ shopId: 1, timestamp: -1 });
predictionLogSchema.index({ shopId: 1, timestamp: -1 });
actualLogSchema.index({ shopId: 1, timestamp: -1 });

const Shop = mongoose.model('Shop', shopSchema);
const Product = mongoose.model('Product', productSchema);
const Customer = mongoose.model('Customer', customerSchema);
const Sale = mongoose.model('Sale', saleSchema);
const Expense = mongoose.model('Expense', expenseSchema);
const Complaint = mongoose.model('Complaint', complaintSchema);
const PredictionLog = mongoose.model('PredictionLog', predictionLogSchema);
const ActualLog = mongoose.model('ActualLog', actualLogSchema);
const ModelRegistry = mongoose.model('ModelRegistry', modelRegistrySchema);

module.exports = {
  db: {
    shops: Shop,
    products: Product,
    customers: Customer,
    sales: Sale,
    expenses: Expense,
    complaints: Complaint,
    predictionLogs: PredictionLog,
    actualLogs: ActualLog,
    modelRegistry: ModelRegistry
  },
  connectDB
};
--.env example--
.venv
